// End-to-end test of the custom font maker in Chromium.
// Usage: NODE_PATH=$(npm root -g) TO_FIXTURES=<dir> node tests/e2e/textures/fonts.e2e.cjs [baseUrl] [--shots <dir>]
// Draws glyphs, turns a tiny TrueType font (generated by tests/tools/fonts/tiny-ttf.cjs, original
// test art) into pixels and embeds it, checks every preview, downloads Java 26.3, Java 1.12.2 and
// Bedrock packs and reads them, opens a pack again, loads the game's font (Java 26.3 client jar
// from TO_FIXTURES, routed locally) and adds the font to a texture pack. Then the page at 390 px
// in light and dark, and translated runs (Russian at 390 px, Japanese at 1280 px).
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { startVite, launch, routeMojang, fixturesDir, unzip, decodePng, jarEntry } = require('./lib.cjs');
const { makeTinyTtf, TEST_GLYPHS } = require('../../tools/fonts/tiny-ttf.cjs');

const argv = process.argv.slice(2);
const baseArg = argv.find((a) => /^https?:/.test(a));
const shotsDir = argv.includes('--shots') ? argv[argv.indexOf('--shots') + 1] : null;
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'tx-fonts-'));
const FONT_JSON = 'assets/minecraft/font/default.json';

let failures = 0;
function check(name, ok, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
}

const json = (b) => (b ? JSON.parse(Buffer.from(b).toString('utf8')) : undefined);

async function rgba(bytes) {
  const img = await decodePng(bytes);
  const out = new Uint8Array(img.width * img.height * 4);
  for (let i = 0; i < img.width * img.height; i++) {
    if (img.channels === 4) out.set(img.data.subarray(i * 4, i * 4 + 4), i * 4);
    else if (img.channels === 2) out.set([img.data[i * 2], img.data[i * 2], img.data[i * 2], img.data[i * 2 + 1]], i * 4);
  }
  return { w: img.width, h: img.height, alpha: (x, y) => out[(y * img.width + x) * 4 + 3] };
}

let downloads = 0;
async function download(page, selector) {
  const [dl] = await Promise.all([page.waitForEvent('download', { timeout: 120000 }), page.click(selector)]);
  const file = path.join(tmp, `${++downloads}-${dl.suggestedFilename()}`);
  await dl.saveAs(file);
  return { file, name: dl.suggestedFilename() };
}

async function shots(page, name, widths = [1280, 390]) {
  if (!shotsDir) return;
  const vp = page.viewportSize();
  for (const theme of ['dark', 'light']) {
    await page.evaluate((t) => (document.documentElement.dataset.theme = t), theme);
    for (const width of widths) {
      await page.setViewportSize({ width, height: width === 390 ? 844 : 860 });
      await page.evaluate(() => {
        window.scrollTo(0, 0);
        document.activeElement?.blur?.();
      });
      await page.waitForTimeout(300);
      await page.screenshot({ path: path.join(shotsDir, `fonts-${name}-${width}-${theme}.png`), fullPage: true });
    }
  }
  await page.evaluate(() => (document.documentElement.dataset.theme = 'dark'));
  await page.setViewportSize(vp);
}

const noOverflow = (page) => page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
const glyphCount = async (page) => Number(((await page.textContent('.fm-chosen .badge')) ?? '').replace(/\D/g, ''));

/** Clicks the pixel (x, y) of the glyph canvas (8 × 12 cells at glyph size 8). */
async function clickPixel(page, x, y) {
  await page.locator('.fm-canvas').scrollIntoViewIfNeeded();
  const box = await page.locator('.fm-canvas').boundingBox();
  await page.mouse.click(box.x + ((x + 0.5) * box.width) / 8, box.y + ((y + 0.5) * box.height) / 12);
}

async function drag(page, from, to) {
  await page.locator('.fm-canvas').scrollIntoViewIfNeeded();
  const box = await page.locator('.fm-canvas').boundingBox();
  const at = ([x, y]) => [box.x + ((x + 0.5) * box.width) / 8, box.y + ((y + 0.5) * box.height) / 12];
  await page.mouse.move(...at(from));
  await page.mouse.down();
  await page.mouse.move(...at(to), { steps: 6 });
  await page.mouse.up();
}

/** Rows of a glyph thumbnail in the character list ('#' = ink). */
const thumbRows = (page, cp) =>
  page.evaluate((c) => {
    const cv = document.querySelector(`.fm-item[data-cp="${c}"] canvas`);
    if (!cv) return null;
    const d = cv.getContext('2d').getImageData(0, 0, cv.width, cv.height).data;
    const rows = [];
    for (let y = 0; y < cv.height; y++) {
      let r = '';
      for (let x = 0; x < cv.width; x++) r += d[(y * cv.width + x) * 4 + 3] > 0 ? '#' : '.';
      rows.push(r);
    }
    return rows;
  }, cp);

async function selectChar(page, ch) {
  const cp = ch.codePointAt(0);
  const groups = { basic: /[!-~]/, cyrillic: /[Ѐ-ӿ]/ };
  const g = Object.entries(groups).find(([, re]) => re.test(ch))?.[0] ?? 'other';
  await page.click(`.fm-group[data-group="${g}"]`);
  await page.click(`.fm-item[data-cp="${cp}"]`);
  await page.waitForFunction((c) => document.querySelector('.fm-char-big')?.textContent === c, ch);
}

/** Waits for `done`, accepting the "Replace your font?" question if it comes. */
async function untilReplaced(page, done, timeout = 30000) {
  const end = Date.now() + timeout;
  while (Date.now() < end) {
    if (await page.evaluate(done)) return true;
    const ask = await page.$('.modal .btn-primary');
    if (ask) await ask.click().catch(() => null);
    await page.waitForTimeout(200);
  }
  return false;
}

async function openPicker(page, source) {
  if (await page.isHidden('.fm-picker')) await page.click('.fm-change');
  await page.click(`.fm-tab[data-source="${source}"]`);
}

async function pickVersion(page, id) {
  await page.click('.fm-version .vp-trigger');
  await page.waitForSelector('.vp-item');
  const search = page.locator('.vp-search input, input.vp-search, [role="combobox"]').first();
  if (await search.count()) await search.fill(id);
  await page.locator('.vp-item', { has: page.locator(`.vp-item-name:text-is("${id}")`) }).first().click();
  await page.waitForFunction((v) => document.querySelector('.fm-version .vp-trigger')?.textContent.includes(v), id);
}

function trackErrors(page, errors) {
  page.on('pageerror', (e) => errors.push(`pageerror ${e.message}`));
  page.on('console', (m) => {
    if (m.type() === 'error' && !/favicon|ERR_|404|Failed to load resource/.test(m.text())) errors.push(m.text());
  });
}

(async () => {
  const fontFile = path.join(tmp, 'TinyTest.ttf');
  fs.writeFileSync(fontFile, makeTinyTtf({ name: 'Tiny Test', glyphs: TEST_GLYPHS }));
  const server = baseArg ? null : await startVite();
  const base = baseArg || server.url;
  const fx = fixturesDir();
  console.log(`base ${base} · fixtures ${fx ?? '(none: real network)'} · tmp ${tmp}`);
  if (shotsDir) fs.mkdirSync(shotsDir, { recursive: true });
  const browser = await launch();
  const errors = [];
  try {
    const ctx = await browser.newContext({ acceptDownloads: true, viewport: { width: 1280, height: 860 }, colorScheme: 'dark' });
    await routeMojang(ctx, fx);
    const page = await ctx.newPage();
    trackErrors(page, errors);

    // ---------------------------------------------------------------- start
    await page.goto(base + 'font-maker');
    await page.waitForSelector('.fm-canvas');
    check('page title', /Minecraft Font Maker/.test(await page.title()), await page.title());
    check('h1', (await page.textContent('.fm-page h1')).trim() === 'Minecraft Font Maker');
    check('starts with the Classic style', (await page.textContent('.fm-chosen-name')).trim() === 'Classic' && (await glyphCount(page)) > 400, String(await glyphCount(page)));
    await page.waitForSelector('[data-tool-intro="fonts"]', { timeout: 15000 }).catch(() => null);
    check('the tool introduction is mounted below the tool', !!(await page.$('[data-tool-intro="fonts"]')));
    check('footer links to the font maker', !!(await page.$('.site-footer a[href$="font-maker/"]')));
    check('the sample is all in the starter font', /Every character/.test(await page.textContent('.fm-missing')));
    await shots(page, '1-start');

    // ---------------------------------------------------------------- draw on a blank grid
    await page.click('.fm-style[data-style="blank"]');
    await page.waitForFunction(() => document.querySelector('.fm-chosen-name')?.textContent.trim() === 'Blank');
    check('Blank: no characters, no question asked (nothing was edited)', (await glyphCount(page)) === 0);
    check('nothing to download yet', await page.isDisabled('.fm-dl-btn'));
    await selectChar(page, 'I');
    await drag(page, [1, 3], [1, 9]);
    await clickPixel(page, 0, 3);
    await clickPixel(page, 2, 3);
    await clickPixel(page, 0, 9);
    await clickPixel(page, 2, 9);
    let rows = await thumbRows(page, 73);
    check('drawn I: a stroke and four serifs', rows && rows[3] === '###.....' && rows[6] === '.#......' && rows[9] === '###.....', rows && rows.slice(3, 10).join('|'));
    check('the width is counted like the game (3 pixels + 1)', /Width 4/.test(await page.textContent('.fm-width')));
    // clicking an inked pixel erases it
    await clickPixel(page, 2, 9);
    rows = await thumbRows(page, 73);
    check('the pencil erases a pixel that is already set', rows[9] === '##......');
    await page.click('.fm-undo');
    rows = await thumbRows(page, 73);
    check('undo', rows[9] === '###.....');
    await page.click('.fm-copy');
    await selectChar(page, 'Ж');
    await page.click('.fm-paste');
    check('copy and paste a glyph', ((await thumbRows(page, 0x416)) ?? []).join() === rows.join());
    await page.click('.fm-starter');
    check('"Classic shape" puts the starter glyph in', ((await thumbRows(page, 0x416)) ?? []).join() !== rows.join());
    await page.fill('.fm-sample', 'Hi Жж 漢');
    const missing = await page.textContent('.fm-missing');
    check('characters not in the font are listed', /H/.test(missing) && /漢/.test(missing) && /i/.test(missing) && !/Ж /.test(missing.split(':')[1] ?? ''), missing.trim());
    await page.click('.fm-group[data-group="other"]');
    await page.fill('.fm-add-input', '★');
    await page.click('.fm-add-btn');
    await page.waitForFunction(() => document.querySelector('.fm-char-big')?.textContent === '★');
    check('a character can be added', (await page.getAttribute('.fm-group[data-group="symbols"]', 'aria-selected')) === 'true');
    await shots(page, '2-drawn');

    // ---------------------------------------------------------------- a font file
    await openPicker(page, 'file');
    await page.setInputFiles('.fm-font-dz input[type=file]', fontFile);
    await page.waitForSelector('.fm-raster:not([hidden])', { timeout: 15000 });
    const info = await page.textContent('.fm-font-info');
    check('the font file is read (name and characters)', /Tiny Test/.test(info) && /9 characters/.test(info), info.trim());
    await page.fill('.fm-raster-size input[type=number]', '8');
    await page.press('.fm-raster-size input[type=number]', 'Enter');
    await shots(page, '3-font-file', [1280]);
    await page.click('.fm-apply');
    await page.waitForFunction(() => /Tiny Test/.test(document.querySelector('.fm-chosen-name')?.textContent ?? ''));
    check('turned into pixels: 9 glyphs (and the drawn ones kept their place)', (await glyphCount(page)) >= 9, String(await glyphCount(page)));
    await page.click('.fm-group[data-group="basic"]');
    for (const ch of ['H', 'g', 'b']) {
      const want = TEST_GLYPHS[ch];
      const got = (await thumbRows(page, ch.codePointAt(0))) ?? [];
      const box = got.slice(3, 3 + want.length).map((r) => r.slice(0, want[0].length));
      check(`rasterised ${ch} is exactly the font's pixels at 8 px`, box.join() === want.join(), box.join('|'));
    }
    await page.click('.fm-embed-toggle .switch');
    await page.waitForFunction(() => /\.ttf/.test(document.querySelector('.fm-chosen')?.textContent ?? ''));
    check('the TrueType file can go in the pack', true);

    // ---------------------------------------------------------------- previews
    await page.fill('.fm-sample', 'Hi Ab');
    for (const s of ['chat', 'sign', 'book', 'title', 'tooltip']) {
      await page.click(`.fm-scene[data-scene="${s}"]`);
      const size = await page.$eval('.fm-scene-canvas', (c) => [c.width, c.height, c.getBoundingClientRect().width]);
      const lit = await page.$eval('.fm-scene-canvas', (c) => {
        const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
        let n = 0;
        for (let i = 3; i < d.length; i += 4) if (d[i]) n++;
        return n;
      });
      check(`preview ${s}: drawn, at least twice the game's size`, size[0] > 40 && lit > 100 && size[2] >= size[0] * 2 - 1, size.join('×'));
      await shots(page, `4-${s}`, [1280]);
    }
    await page.click('.fm-scene[data-scene="chat"]');

    // ---------------------------------------------------------------- Java 26.3
    const vjson = fx ? json(jarEntry(fx, 'version.json')) : null;
    const jz = await download(page, '.fm-dl-btn');
    const j = unzip(jz.file);
    check('Java download: a .zip named after the pack', jz.name === 'My Font.zip', jz.name);
    const fj = json(j[FONT_JSON]);
    const types = (fj?.providers ?? []).map((p) => p.type);
    check('default.json: bitmap then ttf providers', types.join() === 'bitmap,ttf', types.join());
    const bm = fj.providers[0];
    const sheet = j['assets/minecraft/textures/' + bm.file.slice('minecraft:'.length)];
    check('bitmap sheet present, 16 columns, height 12 / ascent 10', !!sheet && bm.chars.every((r) => [...r].length === 16) && bm.height === 12 && bm.ascent === 10);
    check('uniform filter (Force Unicode Font steps over it) on 26.3', bm.filter?.uniform === false);
    const ttfPath = 'assets/minecraft/font/' + fj.providers[1].file.slice('minecraft:'.length);
    check('the .ttf file is in the pack, unchanged', !!j[ttfPath] && Buffer.compare(Buffer.from(j[ttfPath]), fs.readFileSync(fontFile)) === 0, ttfPath);
    const meta = json(j['pack.mcmeta']);
    if (vjson) {
      const want = vjson.pack_version?.resource_major ?? vjson.pack_version?.resource ?? vjson.pack_version;
      const got = meta.pack.pack_format ?? meta.pack.min_format;
      check('pack.mcmeta for 26.3 has its resource pack format', JSON.stringify(got).includes(String(want)), `${JSON.stringify(meta.pack)} vs ${JSON.stringify(vjson.pack_version)}`);
    } else check('pack.mcmeta', !!meta?.pack);
    const icon = await rgba(j['pack.png']);
    check('pack.png 128 × 128', icon.w === 128 && icon.h === 128);
    check('install help shown', /resourcepacks/.test(await page.textContent('.fm-install')));
    await shots(page, '5-downloaded');

    // ---------------------------------------------------------------- Java 1.12.2
    await pickVersion(page, '1.12.2');
    check('1.12.2 hint: ascii.png', /ascii\.png/.test(await page.textContent('.fm-hint')));
    check('1.12.2 preview explains the 8-row grid', /16 × 16/.test(await page.textContent('.fm-target-note')));
    const lz = unzip((await download(page, '.fm-dl-btn')).file);
    const ascii = lz['assets/minecraft/textures/font/ascii.png'];
    check('Java 1.12.2: ascii.png, no default.json, pack_format 3', !!ascii && !lz[FONT_JSON] && json(lz['pack.mcmeta']).pack.pack_format === 3, Object.keys(lz).join());
    const a = await rgba(ascii);
    // 'H' (0x48: column 8, row 4): its left stroke in the cell's first column
    check('ascii.png 128 × 128 with H in its cell', a.w === 128 && a.alpha(64, 32) === 255 && a.alpha(64, 38) === 255);
    await pickVersion(page, '26.3');

    // ---------------------------------------------------------------- Bedrock
    await page.click('.fm-ed-choice[data-value="bedrock"]');
    check('Bedrock: no version picker', await page.isHidden('.fm-version'));
    const bz = await download(page, '.fm-dl-btn');
    const b = unzip(bz.file);
    check('Bedrock download is a .mcpack', bz.name === 'My Font.mcpack', bz.name);
    const manifest = json(b['manifest.json']);
    check('manifest: resources module', manifest?.modules?.[0]?.type === 'resources');
    check('font/default8.png and the Cyrillic page glyph_04.png', !!b['font/default8.png'] && !!b['font/glyph_04.png'], Object.keys(b).join());
    const d8 = await rgba(b['font/default8.png']);
    check('default8.png 128 × 128 with H', d8.w === 128 && d8.alpha(64, 32) === 255);
    const g4 = await rgba(b['font/glyph_04.png']);
    // Ж U+0416: row 1, column 6, 16-pixel cells (each glyph pixel doubled)
    check('glyph_04.png 256 × 256 with Ж', g4.w === 256 && g4.alpha(6 * 16, 16) === 255 && g4.alpha(6 * 16 + 1, 17) === 255);
    check('no .ttf in the Bedrock pack', !Object.keys(b).some((p) => p.endsWith('.ttf')));
    await shots(page, '6-bedrock', [1280]);
    await page.click('.fm-ed-choice[data-value="java"]');

    // ---------------------------------------------------------------- open a pack again
    await openPicker(page, 'pack');
    await page.setInputFiles('.fm-pack-dz input[type=file]', jz.file);
    await untilReplaced(page, () => document.querySelector('.fm-chosen-name')?.textContent.trim() === 'My Font');
    const reopened = await page.textContent('.fm-chosen');
    check('the downloaded pack opens again with its characters and its .ttf', /\.ttf/.test(reopened) && (await glyphCount(page)) >= 9, reopened.trim());
    check('reopened H is the same', ((await thumbRows(page, 72)) ?? []).slice(3, 10).map((r) => r.slice(0, 4)).join() === TEST_GLYPHS.H.join());

    // ---------------------------------------------------------------- the game's font
    if (fx) {
      await openPicker(page, 'game');
      await page.click('.fm-game-btn');
      await untilReplaced(page, () => /Minecraft 26\.3/.test(document.querySelector('.fm-chosen-name')?.textContent ?? ''), 180000);
      const n = await glyphCount(page);
      check('the game’s font of 26.3 is loaded (ascii, accented, nonlatin sheets)', n > 1500, String(n));
      await page.fill('.fm-sample', 'Größe Привет');
      check('game font covers German and Russian', /Every character/.test(await page.textContent('.fm-missing')));
      await shots(page, '7-game-font', [1280]);
    }

    // ---------------------------------------------------------------- into a texture pack
    await page.click('.fm-project-btn');
    await page.waitForSelector('.fm-projects-modal');
    await shots(page, '8-projects', [1280]);
    await page.click('.fm-new-project');
    await page.waitForURL(/textures\/[0-9a-f-]+\/?$/, { timeout: 30000 });
    check('"Add to a texture pack" opens a new texture pack with the font', true);
    await page.goto(base + 'font-maker');
    await page.waitForSelector('.fm-canvas');
    check('the font is kept between visits', /back/.test((await page.textContent('.toast-region, .toasts, body')) ?? '') || (await glyphCount(page)) > 100);

    check('no overflow at 1280', (await noOverflow(page)) <= 0);
    await ctx.close();

    // ---------------------------------------------------------------- 390 px, light and dark
    for (const theme of ['light', 'dark']) {
      const c = await browser.newContext({ acceptDownloads: true, viewport: { width: 390, height: 844 }, colorScheme: theme, isMobile: true, hasTouch: true });
      await c.addInitScript((t) => localStorage.setItem('to-theme', t), theme);
      const p = await c.newPage();
      trackErrors(p, errors);
      await p.goto(base + 'font-maker');
      await p.waitForSelector('.fm-canvas');
      await selectChar(p, 'A');
      await p.locator('.fm-canvas').scrollIntoViewIfNeeded();
      const box = await p.locator('.fm-canvas').boundingBox();
      await p.touchscreen.tap(box.x + (6.5 * box.width) / 8, box.y + (11.5 * box.height) / 12);
      const r = (await thumbRows(p, 65)) ?? [];
      check(`390 ${theme}: tapping draws a pixel`, r[11]?.[6] === '#');
      check(`390 ${theme}: no horizontal overflow`, (await noOverflow(p)) <= 0, String(await noOverflow(p)));
      const canvasW = await p.$eval('.fm-scene-canvas', (cv) => cv.getBoundingClientRect().width);
      check(`390 ${theme}: the preview fits the screen`, canvasW <= 360 && canvasW > 200, String(canvasW));
      await p.click('.fm-ed-choice[data-value="bedrock"]');
      const dl = unzip((await download(p, '.fm-dl-btn')).file);
      check(`390 ${theme}: Bedrock pack downloads`, !!dl['font/default8.png']);
      await p.evaluate(() => window.scrollTo(0, 0));
      if (shotsDir) await p.screenshot({ path: path.join(shotsDir, `fonts-mobile-${theme}.png`), fullPage: true });
      await c.close();
    }

    // ---------------------------------------------------------------- translated
    for (const [lang, width, theme] of [['ru', 390, 'dark'], ['ja', 1280, 'light'], ['de', 390, 'light']]) {
      const c = await browser.newContext({ viewport: { width, height: 860 }, colorScheme: theme });
      await c.addInitScript((t) => localStorage.setItem('to-theme', t), theme);
      const p = await c.newPage();
      trackErrors(p, errors);
      await p.goto(base + `${lang}/font-maker`);
      await p.waitForSelector('.fm-canvas');
      const h1 = (await p.textContent('.fm-page h1')).trim();
      const sample = await p.inputValue('.fm-sample');
      if (lang === 'ru') {
        check('ru: page in Russian', /шрифт/i.test(h1) && /[а-я]/.test(sample), `${h1} · ${sample}`);
        check('ru: the Russian sample is all in the starter font (Cyrillic)', /Все символы|все символы/i.test(await p.textContent('.fm-missing')), (await p.textContent('.fm-missing')).trim());
      } else if (lang === 'ja') {
        check('ja: page in Japanese', /フォント/.test(h1) && /[ぁ-ん]/.test(sample), `${h1} · ${sample}`);
        check('ja: kana and kanji are listed as the game’s font', /[ぁ-ん]/.test(await p.textContent('.fm-missing')));
        await p.click('.fm-group[data-group="kana"]');
        check('ja: kana list with the note on kanji', await p.isVisible('.fm-group[data-group="kana"][aria-selected="true"]'));
      } else {
        check('de: page in German', /Schrift/i.test(h1) && /[äöüß]/.test(sample), `${h1} · ${sample}`);
      }
      const english = await p.evaluate(() => {
        const words = ['Start from', 'Draw your letters', 'In the game', 'Download the pack', 'Pencil', 'Sample text'];
        const t = document.querySelector('.fm-page')?.innerText ?? '';
        return words.filter((w) => t.includes(w));
      });
      check(`${lang}: no English left in the tool`, english.length === 0, english.join(', '));
      check(`${lang}: no horizontal overflow at ${width}`, (await noOverflow(p)) <= 0);
      await p.evaluate(() => window.scrollTo(0, 0));
      if (shotsDir) await p.screenshot({ path: path.join(shotsDir, `fonts-${lang}-${width}-${theme}.png`), fullPage: true });
      await c.close();
    }
    check('no console errors', errors.length === 0, errors.slice(0, 3).join(' | '));
  } catch (err) {
    console.error(err);
    failures++;
  } finally {
    await browser.close();
    server?.stop();
  }
  console.log(failures ? `\n${failures} check(s) failed` : '\nAll font maker checks passed');
  process.exit(failures ? 1 : 0);
})();
